 IEnumerator Run(){Application.runInBackground=true;g=GameContext.Instance.game;original=g.CaptureState();originalSlot=(string)Slot.GetValue(g.saves);auto=g.autoSaveAfterAction;lifecycle=g.autoSaveOnLifecycle;realtime=g.clock.realtimeEnabled;realLife=g.realtimeLifeEnabled;eventChance=g.balance.eventChance;animation=g.world.rules.activityAnimationScale;large=PlayerPrefs.GetInt("ian.ui.largeText",0);background=InputSystem.settings.backgroundBehavior;editorInput=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;Slot.SetValue(g.saves,"phase26-"+Guid.NewGuid().ToString("N")+".json");g.autoSaveAfterAction=g.autoSaveOnLifecycle=g.realtimeLifeEnabled=g.clock.realtimeEnabled=false;g.balance.eventChance=0;
  var stack=new Stack<IEnumerator>();stack.Push(Scenario());while(stack.Count>0){bool more=false;object next=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){result.failure=ex.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator){stack.Push((IEnumerator)next);continue;}yield return next;}
  try{Keys();g.world.rules.activityAnimationScale=animation;g.RestoreState(original);Slot.SetValue(g.saves,originalSlot);g.autoSaveAfterAction=auto;g.autoSaveOnLifecycle=lifecycle;g.realtimeLifeEnabled=realLife;g.clock.realtimeEnabled=realtime;g.balance.eventChance=eventChance;PlayerPrefs.SetInt("ian.ui.largeText",large);InputSystem.settings.backgroundBehavior=background;InputSystem.settings.editorInputBehaviorInPlayMode=editorInput;}catch(Exception ex){result.failure+=" RESTORE "+ex;}result.stage=result.failure==null?"Completed":"Failed";Flush();Destroy(gameObject);
